const UI_EN = {"아직 따뜻한 세탁소": "The Laundry That Stays Warm", "아직 따뜻한": "The Laundry", "세탁소": "That Stays Warm", "이야기로 바로 가기": "Skip to stories", "이야기": "Stories", "세탁소 소개": "About the laundry", "음악 켜기": "Music on", "음악 끄기": "Music off", "하루가 저문 골목을 따라": "Down an alley at the end of the day", "아직 꺼지지 않은 불빛 하나": "A light still burning", "그 문 앞에, 당신이 도착합니다.": "You arrive at its door.", "건너뛰기": "Skip", "골목 끝, 불이 켜져 있습니다": "A LIGHT AT THE END OF THE ALLEY", "오래된 양복 한 벌을 찾아가 달라는": "A call came about collecting", "전화가 왔습니다.": "an old suit.", "이야기를 만나러 가기": "Step into the stories", "골목길 다시 걷기": "Walk the alley again", "이야기가 머무는 곳": "Where stories linger", "천천히, 들어오세요": "Come in. Take your time.", "세탁소에 맡겨진 이야기": "Stories left at the laundry", "옷 한 벌에 남아 있는, 마음 한 조각.": "A piece of a heart, held in a piece of clothing.", "첫 번째 이야기": "The first story", "아버지의 양복": "Father’s Suit", "이야기 읽기": "Read the story", "오래된 골목의,": "In an old alley,", "작은 불빛 하나.": "one small light.", "골목 끝 세탁소에는 십 년이 지나도 찾아가지 않은 옷들이 있습니다.": "At the end of the alley is a laundry with clothes that have gone unclaimed for ten years.", "주인을 기다리는 옷마다 누군가의 시간과 작은 온기가 남아 있습니다.": "In each garment waiting for its owner, a little of someone’s time and warmth remains.", "이곳은 따뜻한 이야기를 만들고 싶은 사람들이 찾아오는 세탁소입니다. 옷 한 벌에 머문 사연을 조심스레 펼치며, 함께 새로운 이야기를 만들어 갑니다.": "This is a laundry for people who want to create stories of warmth. Gently unfolding the lives held in a piece of clothing, we make new stories together.", "첫 번째 이야기 · 01": "The first story · 01", "첫 번째 이야기 · 2장": "The first story · Chapter 2", "오래된 양복을 찾으러 가는 길.": "On the way to collect an old suit.", "세탁소에서 걸려 온 한 통의 전화가 잊고 있던 시간을 불러옵니다.": "A call from the laundry brings a forgotten time back into reach.", "세탁소로 돌아가기": "Back to the laundry", "이야기 목록": "Story list", "이 이야기는 창작된 소설입니다.": "This story is a work of fiction.", "2장 읽기": "Read Chapter 2", "1장으로": "Chapter 1", "1장으로 돌아가기": "Back to Chapter 1", "2장 처음으로": "Top of Chapter 2", "2장": "Chapter 2", "처음으로": "Back to the start", "장면 전환": "Scene break", "닫기": "Close", "배경 음악": "Background music", "주 메뉴": "Main navigation", "아직 따뜻한 세탁소, 처음으로": "The Laundry That Stays Warm, home", "골목길 오프닝 다시 보기": "Replay the alley opening", "아래 이야기 목록으로 이동": "Go to the story list below", "세탁소로 향하는 10초의 골목길": "A ten-second walk to the laundry", "비가 그친 오래된 한국 골목. 낡은 세탁소의 유리창 너머로 옷과 수건, 따뜻한 불빛이 보인다.": "An old Korean alley after the rain. Clothes, towels and warm light glow behind the windows of a weathered laundry.", "음악을 재생하지 못했어요. 다시 눌러 주세요.": "The music could not play. Please try again.", "음악을 불러오지 못했어요. 연결을 확인하고 다시 눌러 주세요.": "The music could not load. Check your connection and try again."};
const CHAPTER_ONE_EN = ["The message was brief.", "This is Saebom Laundry. We’re getting in touch about a suit left with us under the name Jeong Gi-tae. Please stop by when it’s convenient.", "Her father had been dead for five years. This was the first time anyone had contacted her in his name. For three days, Seoyun could not bring herself to delete the message. She did not reply, either. On the third evening she called, and the man on the other end said, ‘You can come tomorrow afternoon,’ without asking anything more. Seoyun asked nothing more, either. In that respect, the conversation suited them both.", "The following afternoon, in an alley where the rain had just stopped, Seoyun stood beneath the cleaners’ sign. ‘Saebom Laundry,’ in white letters on blue. The edges of the lettering had worn away. As a child, she had walked down this alley on her way to school. She must have passed the shop countless times, but she had no memory of going inside. What she did remember was the white steam rising from the vent in winter.", "A bell gave a short ring as she pushed the door open.", "‘Hello.’", "A man looked up from the ironing board. He seemed to be about sixty. His forearms, exposed by his rolled-up sleeves, were lean and firm. He set the iron upright with a quick movement.", "‘I’m Jeong Seoyun. I called yesterday.’", "‘Yes. You’re his daughter.’", "The man glanced at Seoyun’s face. He did not look for long.", "‘I remember your father’s face. You have his eyes.’", "She had heard that several times at the funeral. But here in the shop, it sounded different. Seoyun gave only a small nod.", "‘Did my father come here often?’", "‘He used to bring in his shirts. On Saturdays, if I remember correctly.’", "On Saturdays, her father would go out in the morning and come home around lunchtime. Seoyun had never asked where he went, and he had never told her. It must have been this alley, she thought, only now.", "The man went into the back and returned with a suit in a clear garment bag. It was dark navy. Under the fluorescent lights, the fabric had a quiet, subdued depth.", "Seoyun recognized it. They had chosen it together at the made-to-measure counter of a department store one spring more than ten years ago, two months before her wedding. Her father had looked at the price tag and said once, ‘What do I need something this good for?’ Seoyun had answered once, ‘Please wear it.’ That was the end of it.", "‘When was it brought in?’", "The man took an old ledger from beneath the counter and turned it toward her. ‘Jeong Gi-tae / Suit jacket and trousers / Storage.’ The ink in the date column had run, perhaps from water, and was unreadable.", "‘I’m not sure myself. The ink has run. I noticed the name while I was going through the ledger. It was definitely left under your father’s name.’", "The man detached a small paper tag from the ledger and held it out. There were two phone numbers, written one above the other in firmly pressed pencil. The upper number had been crossed out. Seoyun recognized it as the landline at their old house. Below it was her own number. The top of the numeral 4 was open. It was the way her father wrote his fours.", "‘The first number was disconnected, so I called the one below.’", "‘…Yes.’", "‘Would you like to feel it?’", "The man unzipped the garment bag. It was less an invitation than a way of stepping aside.", "‘With the clothes in this shop, you’ll know when you touch them. There’s nothing I can explain.’", "Seoyun did not ask what he meant. She reached out and placed her hand on the shoulder.", "It was warm.", "The shop was cool, and the other clothes hanging beside it were cold. Only the shoulder of this suit held warmth, like a mug someone had just taken their hand away from. As she pressed the fabric, the warmth rose into her palm in equal measure. It was like clothing freshly ironed, but much softer than that.", "Seoyun did not lift her hand. The shoulder had been pressed into a clean, straight line.", "‘Did you iron this here?’", "‘We haven’t touched it. We’ve kept it just as it was when it was brought in.’", "That was all the man said. Seoyun asked nothing more.", "She tried to remember the last time her father had worn this suit. On her wedding day, he had stood at the entrance to the hall with his shoulders squared. Unused to wearing a tie, he had lifted his chin several times as though it felt tight. She thought the suit had gone into the wardrobe when they got home after the ceremony. After that, the father Seoyun remembered was always in a brown casual jacket or an old gray one. Every time she saw him dressed that way, she felt a little hurt. But she had never asked him to wear the suit.", "Her hand moved down to the sleeve.", "The end of the right sleeve was worn softer than the left. It looked like the wear of someone who often rested his arm on something. Of the four sleeve buttons, one was different from the others. The thread was a little darker, wound around more times, with a large, round knot. It looked as though an unpracticed hand had wound it over and over to make it hold.", "When she touched the button with her fingertip, the warmth grew a little stronger there.", "‘This button…’", "‘That wasn’t my work.’", "Seoyun had never seen her father hold a needle. For a moment, she pictured him squinting as he tried to thread one. But it was a scene she had never witnessed. She let the image go no further. Her finger stayed on the button for a while.", "Without a word, the man poured some barley tea and set it on the counter. It was a long time before Seoyun even noticed the cup was there.", "Last, she opened the left inside pocket. When she slipped her fingers in, the warmth was strongest there. If the other places were like a mug, this was like a palm she had just held and let go. The pocket was empty. Its lining bore the marks of something that had been folded, put inside, and taken out again. The shape was long and horizontal, about the size of a sheet of paper folded once. The fabric there had a faint nap, and a few stitches had come loose along one seam, leaving a very small opening.", "‘We ask for the pockets to be emptied before we take clothes in. I don’t know what was in there.’", "With her hand still in the pocket, Seoyun wondered. Had it been the wedding invitation? A sheet with the order of the ceremony? It might have been the note she had sent with the invitation. ‘Dad, please come.’ She remembered writing just that much. There was no way to know. It might not have been paper at all, but something entirely different. The warmth told her none of this. It was simply there.", "‘I thought my father never wore this suit. After the wedding.’", "She spoke as though to herself. The man did not hurry to answer.", "‘I never saw your father wearing it. That much I can say for certain.’", "‘…Yes.’", "‘Beyond that, there’s nothing I can tell you.’", "Seoyun nodded. If anything, his words put her at ease. No one needed to unravel it for her. She was grateful that a suit she had thought he hadn’t worn carried these traces of being handled. She was hurt that she had never seen those traces before. Both feelings lay together in one palm. Neither erased the other.", "Seoyun picked up the barley tea. It had gone cold. Only the palm of her right hand, wrapped around the cup, was still warm.", "‘Would you like to take it with you?’", "The man asked without any sign of hurrying her.", "Seoyun looked down at the suit once more. She tried to think where she would hang it if she took it home. Not on the coat rack by the door, not in the wardrobe, not beside the chest of drawers. None of those places seemed right. She did not know what this warmth would become if she brought it into her home. She could not tell whether she was afraid of that or reluctant to let it change.", "‘Could you mend the lining of the inside pocket? The seam has come loose. I think it might open up more if it’s left like this.’", "The man turned the inside pocket out and lightly pressed the open seam with his fingers.", "‘I can do that. Just that part?’", "‘Yes. Just that part. Please leave the button as it is, and don’t press the shoulders again.’", "‘All right.’", "‘Could I leave it here even after you’ve mended it? I don’t know when I’ll come to collect it. It could be tomorrow, or it could take longer.’", "The man looked at Seoyun. He did not seem surprised. He nodded once, like someone who had spent many years ironing.", "‘Then I’ll keep it hanging here. Come when you’ve decided.’", "‘What will it cost?’", "‘I’ll tell you when you come to collect it.’", "On the back of the tag, the man wrote ‘Inside pocket repair’ in pencil and attached it to the suit’s sleeve. Then he put the suit in its bag, zipped it up, and hung it on the rail at the back. Among the other clothes, the navy fabric soon became hard to pick out. Seoyun watched for a moment.", "Outside the door, she caught the smell of wet pavement. Seoyun put her hands in her coat pockets. Her right hand was still warm. She could not tell whether the warmth came from the shoulder, the inside pocket, or the time she had spent holding the cup of barley tea.", "After walking for some time, she looked back and saw white steam rising from the vent. For a moment, Seoyun watched it disperse above the alley.", "Then she walked on, slowly opening and closing her fingers inside her pocket."];
const CHAPTER_TWO_EN = ["The text saying the repair was finished had come a week ago.", "This is Saebom Laundry. The inside pocket repair you requested is finished. Please stop by whenever it is convenient.", "This time, Seoyun did not wait three days. She read the message and closed it at once. Then she stayed away all week. On Monday she had to work late, on Wednesday it rained, and on Friday she had to buy groceries. Each reason was real. As one real reason followed another, Seoyun did not ask herself whether they were reasons or excuses.", "On Saturday morning, Seoyun went to her family home.", "The house had stood empty since her father died. Seoyun stopped by once a month or so to air it out and clear away the mail. This time, as soon as she stepped through the front door, she went straight to the main bedroom. When she opened the wardrobe, the smell of mothballs came out first.", "The brown jacket hung at the far left. It was an old jacket, faded almost white at the inner elbows. Beside it was a gray jacket. Its shoulders sagged a little, shaped to her father's body.", "Seoyun took out the brown jacket first. She laid a hand on its shoulder.", "It was cold.", "It was simply the temperature of clothing. The fabric had hung in a cool room for a long time, and it was cool. Seoyun felt the sleeve, put her hand in a pocket, and held the collar to her nose. Beneath the mothballs was a faint smell like old soap. That was all.", "The gray jacket was the same. Its shoulders, sleeves, and inside pocket were all cold. An old chewing-gum wrapper came out of the right pocket. Seoyun laid it on her palm and looked at it for a long time before putting it back.", "She sat on the floor with both jackets across her knees. These were the clothes her father had worn every day. Seoyun found it strange that the clothes he had worn every day should tell her nothing. There had been warmth in the suit she had thought he never wore, but none in the clothes he had worn. She did not know why. Nor was it something she could ask anyone about. Seoyun sat for a while with the question resting on her knees.", "Outside the window, she heard water, as though someone were watering their plants.", "As she hung the brown jacket back in the wardrobe, Seoyun noticed an empty hanger on the back wall. It was wooden, with broad shoulders. A suit hanger. She looked at it for a moment, then closed the door without touching it.", "As she left the house, Seoyun turned the key twice.", "The following Monday, she took a bus toward the laundry, then got off two stops early. She stopped at a convenience store and bought water she did not need. On Tuesday, a coworker asked her to lunch and she went along. On the way back, she walked past the subway exit that led toward the laundry. On Wednesday, she really had no time.", "On Thursday evening, on her way home from work, Seoyun turned into the alley without planning to.", "The shop lights were on. Steam rose from the ventilation window. Seoyun paused beneath the sign, then pushed open the door. The bell gave a brief ring.", "“Hello.”", "The man was at the ironing board. This time he only raised his head, then lowered it again. He looked neither as though he had expected her nor as though he was surprised.", "“You said the repair was finished. It's taken me a while to come.”", "“That's all right.”", "The man stood the iron upright and brought the suit from a rail farther inside the shop. It was in a clear cover. On the tag attached to the sleeve, ‘Inside pocket repair’ was written in pencil. Just as Seoyun had seen it that day.", "“Will you be taking it with you?”", "“I'd just like to touch it for a moment.”", "“Of course.”", "The man returned to the ironing board. Seoyun unzipped the cover.", "She laid her hand on the shoulder. It was warm. She could not tell whether it was the same warmth as before. It seemed a little fainter than last time, though perhaps it only felt that way because her hand was cold. Her hands had been out in the evening air on her way from work. That should have made the suit feel warmer, yet it seemed less warm instead. Seoyun closed her hand, opened it, and laid it on the shoulder again. She could not reach the same conclusion.", "The sleeve button was unchanged. Dark thread and a large, round knot. Seoyun pressed the button once with her fingertip. The warmth was there too. Again, she could not be sure whether it was a little stronger than at the shoulder, or the same.", "She opened the inside pocket.", "The split seam of the inside pocket had been neatly joined with new thread. The stitches were small and close, in a straight line. Seoyun slipped her fingers inside.", "There was warmth.", "She could not tell whether it was the same warmth as before the repair. Then, it had felt like a palm she had just held and let go of. Now, it felt as though she were laying her hand where a palm had been. Seoyun tried to put the difference into words, then stopped. It was only a feeling, and she did not know whether it belonged to the clothes or to her. The marks of the folds were still there. Even with the seam mended, the fabric, slightly raised over an area the size of a piece of paper, had not flattened.", "“I left those marks as they were.”", "The man spoke from the ironing board without turning around.", "“The fabric has settled into that shape. I could press them out, but you didn't ask me to, so I left them.”", "“Yes. I like them as they are.”", "Seoyun answered. Only after she had answered did she realize that was how she felt.", "For a while, Seoyun stood with her hand in the pocket. The only sounds in the shop were the water boiling in the iron and the ticking of the clock. However long she stood there, no one hurried her.", "She thought of the jackets in the wardrobe at home. The clothes that had been cold. Seoyun considered mentioning them, then decided against it. Even if she asked, this man would not be able to answer. He had not explained the warmth last time either.", "“Could I bring in the clothes my father used to wear, too? Even if they aren't warm?”", "Seoyun asked. The words surprised her once she had said them.", "The man took his hand off the iron and thought for a moment.", "“I can clean them for you. I don't know whether any warmth will remain.”", "“Yes. That's all right.”", "“Then you can bring them in.”", "Seoyun nodded. She did not know what would change if she brought the two jackets. They were more likely to come back cold. Still, it did not seem a bad thing for the clothes her father had worn every day to be neatly pressed by someone's hands, at least once. Seoyun had never thought of leaving those clothes with someone to be cared for.", "Seoyun zipped up the cover.", "“I'll leave it here again today.”", "“All right.”", "“When I bring the jackets, I'll decide whether to take it home then.”", "“All right.”", "The man gave the same answer. Seoyun did not mind that.", "At the door, Seoyun looked again at the tag on the sleeve. Beside ‘Inside pocket repair,’ something else had been written in small pencil letters. ‘Finished.’ It had not been there when she first came.", "Seoyun looked at the word for a moment, then opened the door.", "Evening lights had come on in the alley. Steam from the ventilation window spread white beneath the streetlamp. Seoyun put her hands in her coat pockets. Her right hand had cooled. Still, for a while she wanted to believe that the fingertips that had touched the inside pocket were warm. She did not know whether she could let herself believe it.", "As she walked to the bus stop, Seoyun thought she should go to her family home the following Saturday. She would be going to get the clothes. That was all."];
const languageSelect = document.querySelector('#language-select');
const uiTextNodes = [];
const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
while (walker.nextNode()) {
  const node = walker.currentNode;
  if (node.parentElement.closest('.story-body,script,select,.language-control')) continue;
  const key = node.textContent.trim();
  if (Object.hasOwn(UI_EN,key)) uiTextNodes.push({node,original:node.textContent,key});
}
const attributes = [];
document.querySelectorAll('[aria-label],[alt]').forEach(el => {
  ['aria-label','alt'].forEach(attr => {
    const value = el.getAttribute(attr);
    if (Object.hasOwn(UI_EN,value)) attributes.push({el,attr,value});
  });
});
const paragraphs = [...document.querySelectorAll('.story-body p')].map(el=>({el,original:el.innerHTML}));
const englishParagraphs = [...CHAPTER_ONE_EN,...CHAPTER_TWO_EN];
if (paragraphs.length !== englishParagraphs.length) throw new Error('Translation paragraph count mismatch');
window.laundryText = text => document.documentElement.lang === 'en' ? UI_EN[text] || text : text;
function applyLanguage(lang, preservePosition = true) {
  const activeReader = [...document.querySelectorAll('.chapter-reader')].find(el=>!el.hidden);
  const anchor = preservePosition && activeReader ? [...activeReader.querySelectorAll('h1,.story-body p,.fiction-note')].find(el=>el.getBoundingClientRect().bottom>110) : null;
  const offset = anchor ? anchor.getBoundingClientRect().top : 0;
  document.documentElement.lang = lang;
  languageSelect.value = lang;
  uiTextNodes.forEach(({node,original,key})=>{node.textContent = lang==='en' ? original.replace(key,UI_EN[key]) : original;});
  attributes.forEach(({el,attr,value})=>el.setAttribute(attr,lang==='en'?UI_EN[value]:value));
  paragraphs.forEach(({el,original},i)=>{
    if(lang==='ko') el.innerHTML=original;
    else { const em = el.querySelector('em'); if(em) em.textContent=englishParagraphs[i]; else el.textContent=englishParagraphs[i]; }
    el.lang=lang;
  });
  document.querySelectorAll('.chapter-reader').forEach(el=>el.lang=lang);
  const second=location.hash==='#father-suit-2';
  document.title=activeReader ? window.laundryText('아버지의 양복')+(second?' · '+window.laundryText('2장'):'')+' · '+window.laundryText('아직 따뜻한 세탁소') : window.laundryText('아직 따뜻한 세탁소');
  updateMusicUI(!music.paused && !music.muted);
  try { sessionStorage.setItem('warm-laundry-language',lang); } catch(_) {}
  if(anchor) window.scrollBy({top:anchor.getBoundingClientRect().top-offset,behavior:'instant'});
}
languageSelect.addEventListener('change',()=>applyLanguage(languageSelect.value));
let preferredLanguage='ko';
try { if(sessionStorage.getItem('warm-laundry-language')==='en') preferredLanguage='en'; } catch(_) {}
applyLanguage(preferredLanguage,false);
